from lib import *
S = SS('x102')
steps = [
    step("什么都不配,只加 spring-boot-starter-security:Servlet 容器里登记了一个名叫 springSecurityFilterChain 的 DelegatingFilterProxy,order=-100;它背后是 FilterChainProxy,里面只有 1 条 SecurityFilterChain,匹配规则是 any request,共 16 个过滤器,顺序是:DisableEncodeUrlFilter、WebAsyncManagerIntegrationFilter、SecurityContextHolderFilter、HeaderWriterFilter、CsrfFilter、LogoutFilter、UsernamePasswordAuthenticationFilter、DefaultResourcesFilter、DefaultLoginPageGeneratingFilter、DefaultLogoutPageGeneratingFilter、BasicAuthenticationFilter、RequestCacheAwareFilter、SecurityContextHolderAwareRequestFilter、AnonymousAuthenticationFilter、ExceptionTranslationFilter、AuthorizationFilter。所有 URL(/api/x、/other、/ignored/x 等)都经过同样的 16 个。请求 GET /x 不带凭据:HTTP 401,WWW-Authenticate: Basic realm=\"Realm\";带 Basic u:p:HTTP 200;两种情况的响应里都有 x-content-type-options、x-frame-options、cache-control 三个安全响应头(HeaderWriterFilter 写的)。", t=tl(S(1)), mark=lidx(S(1), '16 个', 'ExceptionTranslationFilter', 'AuthorizationFilter'), done=lidx(S(1), 'DelegatingFilterProxy', 'FilterChainProxy 里有 1 条', 'HeaderWriterFilter', 'GET /x'), b=bars([['默认链里的过滤器个数', 16, '16'], ['FilterChainProxy 里的链个数', 1, '1'], ['DelegatingFilterProxy 的 order', -100, '-100'], ['不带凭据的 HTTP 状态码', 401, '401']], 401, done=[0, 1], mark=[2, 3]), kv=KV([['入口', 'DelegatingFilterProxy(order=-100) → FilterChainProxy'], ['默认链', 'any request,16 个过滤器'], ['顺序', 'Csrf 在 Logout 之前,Authorization 在最后'], ['响应头', '默认带 x-content-type-options 等']], ['默认链'])),
    step("自己写两条链:链 1 = securityMatcher(\"/api/**\") + httpBasic,@Order(1),11 个过滤器(我关掉了 csrf、也没配表单登录,所以没有 CsrfFilter 和 UsernamePasswordAuthenticationFilter);链 2 = 兜底(any request)+ formLogin,@Order(2),15 个过滤器。FilterChainProxy 对每个请求只选第一条匹配的链:/api/x 经过 11 个、含 BasicAuthenticationFilter;/other、/open/x 经过 15 个、含 UsernamePasswordAuthenticationFilter。一个很容易漏的地方:GET /api/x 不带凭据,期望 401,实际得到 HTTP 302,Location 是 /login;jsessionid=…(同时响应里还带着 WWW-Authenticate: Basic)——链 1 确实先返回了 401,但 sendError 触发了对 /error 的错误派发,/error 不属于 /api/**,被兜底的链 2 拦下,要求登录,于是重定向到 /login。在链 2 里把 /error 也 permitAll 之后,同样的请求才是想要的 HTTP 401。带 Basic u:p 的请求两种配置下都是 200。", t=tl(S(2)), mark=lidx(S(2), 'GET /api/x → HTTP 302', '链 2 里多了 /error 的 permitAll'), done=lidx(S(2), '链 1 = securityMatcher(/api/**) @Order(1)', 'URL /api/x', 'URL /other', 'GET /api/x → HTTP 401'), b=bars([['/api/** 链的过滤器个数', 11, '11'], ['兜底链的过滤器个数', 15, '15'], ['没放行 /error 时 GET /api/x 的状态码', 302, '302'], ['放行 /error 之后', 401, '401']], 401, done=[0, 1, 3], mark=[2]), kv=KV([['匹配', '只选第一条匹配的链,/api/x 不会再进链 2'], ['/api/** 链', '11 个过滤器(我关了 csrf、没配表单登录)'], ['/error', '错误派发会被兜底链再拦一次,要 permitAll'], ['症状', '期望 401,实际 302 到 /login']], ['/error'])),
    step("顺序写反:把兜底链(any request)放在前面 @Order(1),securityMatcher(\"/api/**\") 的链放在后面 @Order(2)。应用启动就失败:BeanCreationException … Factory method 'springSecurityFilterChain' threw exception with message: A filter chain that matches any request [… defined as 'web' …] has already been configured, which means that this filter chain [… defined as 'api' … matching [Or [PathPattern [/api/**]]] …] will never get invoked. Please use `HttpSecurity#securityMatcher` to ensure that there is only one filter chain configured for 'any request' and that the 'any request' filter chain is published last.——这个版本在启动时就检查出「后面的链永远不会被调用」,而不是悄悄让它失效。", t=tl(S(3)), mark=lidx(S(3), '应用启动失败'), done=[], b=bars([['顺序写反时应用能否启动(0=不能)', 0, '不能'], ['启动失败时报出被遮蔽的链的个数', 1, '1(api 链)']], 1, mark=[0, 1]), kv=KV([['兜底链放前面', '启动失败,不是悄悄失效'], ['报错内容', 'A filter chain that matches any request … will never get invoked'], ['建议', '带 securityMatcher 的链在前,兜底链最后'], ['一条兜底', '只能有一条 any request 的链,且发布在最后']], ['兜底链放前面'])),
    step("ignoring 与 permitAll 的区别。配置 WebSecurityCustomizer 的 ignoring().requestMatchers(\"/ignored/**\") 之后,FilterChainProxy 里多了一条匹配 /ignored/** 的链,过滤器 0 个;/ignored/x 实际会经过的过滤器是 0 个,不经过 Spring Security,响应头里没有任何安全响应头(安全相关响应头 [])。同一个应用里 permitAll 的 /permitted/x 仍然经过 11 个过滤器,响应头里有 x-content-type-options、x-frame-options、cache-control,只是授权放行。没有放行的 /secret 返回 HTTP 403(这个配置里既没有 httpBasic 也没有 formLogin,没有认证入口可以引导登录)。静态资源可以 ignoring,需要安全响应头或需要拿到认证信息的路径用 permitAll。", t=tl(S(4)), mark=lidx(S(4), 'GET /ignored/x', '/secret'), done=lidx(S(4), 'GET /permitted/x', 'URL /ignored/x'), b=bars([['/ignored/** 链的过滤器个数', 0, '0'], ['permitAll 的路径经过的过滤器个数', 11, '11'], ['/ignored/x 响应里的安全相关响应头个数', 0, '0'], ['/permitted/x 响应里的安全相关响应头个数', 3, '3']], 11, mark=[0, 2], done=[1, 3]), kv=KV([['ignoring', '链里 0 个过滤器,完全绕过 Spring Security'], ['permitAll', '仍经过 11 个过滤器,响应头照写'], ['/secret', '没有认证入口时返回 403'], ['选择', '静态资源可以 ignoring,其他用 permitAll']], ['ignoring'])),
]
A = mkartx('x102', 102, 'Spring,Security,FilterChainProxy,过滤器链,securityMatcher,真实验证,动画演示',
    '实测 Spring Security 7 的 FilterChainProxy:默认链有 16 个过滤器;两条链时每个请求只选第一条匹配的链(/api/** 链 11 个、兜底链 15 个);401 触发的 /error 派发会被兜底链拦下变成 302 到 /login;兜底链放在前面会在启动时失败;ignoring 的路径完全不经过过滤器,没有安全响应头,permitAll 的路径仍然经过 11 个过滤器。',
    '安全过滤器链到底有哪些过滤器、什么顺序?多条链怎么选?为什么 API 应该返回 401 却变成跳转登录页?ignoring 和 permitAll 差在哪?这篇在 Spring Boot 4.0.8、Spring Security 7 上直接打印 FilterChainProxy,再发请求验证。',
    [('16 个', '什么都不配时默认安全过滤器链的过滤器个数'), ('401 → 302', '多链时,没放行 /error,期望 401 的 /api/x 变成跳转到 /login'), ('0 个', 'web.ignoring() 的路径在 FilterChainProxy 里的过滤器个数')],
    [('默认链', '<p>一条 any request 链,16 个过滤器;入口是 order=-100 的 DelegatingFilterProxy。</p>'),
     ('多条链', '<p>只选第一条匹配的链;/error 的错误派发要在兜底链里放行,否则 401 会变成 302。</p>'),
     ('顺序写反', '<p>兜底链放前面会在启动时失败并指出被遮蔽的链。</p>'),
     ('ignoring 与 permitAll', '<p>ignoring 完全绕过过滤器链,没有安全响应头;permitAll 仍经过链。</p>')],
    steps,
    [ENV_X + '(Spring Security 7 随 spring-boot-starter-security)。一个 @RestController 对所有路径返回 ok;默认用户 u / p;过滤器清单与链的匹配规则取自 FilterChainProxy.getFilterChains(),每个 URL 实际经过的过滤器取自 FilterChainProxy.getFilters(url);HTTP 响应用 Python http.client 取得,不自动跟随重定向',
     '没有验证:Spring Security 7 里 SecurityFilterChain 的更多扩展(如 securityMatchers 与 MVC 匹配器的差别);自定义过滤器 addFilterBefore / addFilterAfter 的位置;ASYNC 与 FORWARD 派发的授权规则(shouldFilterAllDispatcherTypes);Spring Security 对静态资源的默认行为;响应式 WebFlux 的 SecurityWebFilterChain'],
    'FilterChainProxy')
